-- STEP 4: WRAP HELPER
-- ═══════════════════════════════════════════════════════════════════
local PFX = "__v17_"
local function wrap(mod, name, wrapper)
    if not mod or type(mod[name]) ~= "function" then return false end
    if not mod[PFX .. name] then mod[PFX .. name] = mod[name] end
    mod[name] = wrapper(mod[PFX .. name])
    return true
end

