-- NICKNAME COLOR — Self-Only Legend Color (61910004)
-- Copied from skin.lua (P23-FIX Task2). Active.lua me yeh block missing tha.
-- ==============================================================================
pcall(function()
    local SELF_COLOR_ID = 61910004 -- Ultimate Royale Legend (sirf self)
    local function TryApplySelfNicknameColor()
        if not _G.DataMgr or not _G.DataMgr.roleData or not _G.DataMgr.roleData.uid then
            return false
        end
        local MM = _G.ModuleManager
        if not MM or not MM.GetModule or not MM.CommonModuleConfig then return false end
        local ok, NCM = pcall(function()
            return MM.GetModule(MM.CommonModuleConfig.NicknameColorManager)
        end)
        if not ok or not NCM then return false end
        if NCM.DEFAULT_PLAN_ID == nil then NCM.DEFAULT_PLAN_ID = 61910002 end
        if not NCM._p23_selfOnlyHooked then
            NCM._p23_selfOnlyHooked = true
            NCM._orig_GetUserData_p23 = NCM.GetUserData
            function NCM:GetUserData(UID)
                if UID ~= nil and _G.DataMgr and _G.DataMgr.roleData and _G.DataMgr.roleData.uid then
                    if tostring(UID) == tostring(_G.DataMgr.roleData.uid) then
                        return SELF_COLOR_ID
                    end
                end
                return self._orig_GetUserData_p23(self, UID)
            end
            NCM._orig_SetUserData_p23 = NCM.SetUserData
            function NCM:SetUserData(UID, planID)
                if UID ~= nil and _G.DataMgr and _G.DataMgr.roleData and _G.DataMgr.roleData.uid then
                    if tostring(UID) == tostring(_G.DataMgr.roleData.uid) then
                        planID = SELF_COLOR_ID
                    end
                end
                return self._orig_SetUserData_p23(self, UID, planID)
            end
            if NCM.GetCurColor and not NCM._orig_GetCurColor_p23 then
                NCM._orig_GetCurColor_p23 = NCM.GetCurColor
                function NCM:GetCurColor() return SELF_COLOR_ID end
            end
        end
        local selfUID = _G.DataMgr.roleData.uid
        pcall(function() NCM:SetUserData(selfUID, SELF_COLOR_ID) end)
        pcall(function()
            if _G.EventSystem and _G.EVENTTYPE_COLLECT and _G.EVENTID_COLLECT_NICKNAME_COLOR_CHANGE then
                _G.EventSystem:postEvent(_G.EVENTTYPE_COLLECT,
                    _G.EVENTID_COLLECT_NICKNAME_COLOR_CHANGE, tostring(selfUID))
            end
        end)
        return true
    end
    pcall(TryApplySelfNicknameColor)
    -- Retry loop: NicknameColorManager ready hone ka wait
    pcall(function()
        local okT, tt = pcall(require, "common.time_ticker")
        if okT and tt and tt.AddTimerLoop and tt.RemoveTimer then
            local timer = nil
            timer = tt.AddTimerLoop(2, function()
                local ok, res = pcall(TryApplySelfNicknameColor)
                if ok and res then pcall(function() tt.RemoveTimer(timer) end) end
            end, -1, 2)
            tt.AddTimerOnce(60, function()
                pcall(function()
                    if timer and tt.IsRunning(timer) then tt.RemoveTimer(timer) end
                end)
            end)
        end
    end)
end)

