-- AVATAR FRAME — skin.lua Method (Final)
-- Purana system delete hone ke baad yeh paste karo. Sab real frames unlock,
-- silver coin / bad IDs auto-reject. Self-only, no server send.
-- ═══════════════════════════════════════════════════════════════════════════
pcall(function()
    if _G._AVFRAME_FINAL then return end
    _G._AVFRAME_FINAL = true

    local function isRealAvatarFrame(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        local frameCfg = CDataTable.GetTableData("AvatarFrame", resID)
        if not frameCfg then return false end
        local itemCfg = CDataTable.GetTableData("Item", resID)
        if itemCfg then
            local itemType = tonumber(itemCfg.ItemType or itemCfg.itemType or 0)
            if itemType == 4 then return false end
            local name = tostring(itemCfg.ItemName or "")
            local lower = string.lower(name)
            if string.find(lower, "coin", 1, true)
               or string.find(lower, "silver", 1, true) then
                return false
            end
        end
        return true
    end
    _G.RoxzIsRealAvatarFrame = isRealAvatarFrame

    local function install()
        if not CDataTable or not CDataTable.GetTable then return false end
        if CDataTable._RoxzAvFrameHook then return true end
        CDataTable._RoxzAvFrameHook = true

        local origGetTable = CDataTable.GetTable
        CDataTable.GetTable = function(...)
            local name = select(1, ...)
            local ret = origGetTable(...)
            if name == "AvatarFrame" and ret then
                pcall(function()
                    local sys = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
                    if not sys then return end
                    local newList = {}
                    if sys.AvatarFrameList then
                        for k, v in pairs(sys.AvatarFrameList) do
                            newList[k] = v
                        end
                    end
                    for k, cfg in pairs(ret) do
                        local id = tonumber(type(cfg) == "table" and (cfg.ID or cfg.id) or k)
                        if id and id > 0 and isRealAvatarFrame(id) then
                            newList[id] = { id = id, expire_time = 0, expire_ts = 0 }
                        end
                    end
                    sys.AvatarFrameList = newList
                    sys.HasAvatarFrame = function() return true end
                    sys.HasAvatarFrameCond = function() return true end
                    if sys.IsLocked then sys.IsLocked = function() return false end end
                    if sys.CheckAvatarFrameValid then sys.CheckAvatarFrameValid = function() return true end end
                end)
            end
            return ret
        end

        pcall(function()
            local RAS = require("client.slua.logic.roleInfo.logic_roleInfo_Avatar")
            local RAF = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
            if RAF then
                local oldRsp = RAF.change_avatar_box_rsp
                if oldRsp and not RAF._RoxzFinalChange then
                    RAF._RoxzFinalChange = oldRsp
                    RAF.change_avatar_box_rsp = function(ok, item_id)
                        if ok ~= 0 then ok = 0 end
                        item_id = tonumber(item_id)
                        if item_id and item_id > 0 and not isRealAvatarFrame(item_id) then
                            print("[AVFRAME] Rejected bad ID:", item_id)
                            return RAF._RoxzFinalChange(ok, nil)
                        end
                        return RAF._RoxzFinalChange(ok, item_id)
                    end
                end
            end
        end)

        pcall(function()
            local CH = require("client.network.Protocol.CharacterHandler")
            if CH and not CH._RoxzFinalAvBox then
                CH._RoxzFinalAvBox = true
                local oldSend = CH.send_change_avatar_box
                if oldSend then
                    CH.send_change_avatar_box = function(item_id)
                        item_id = tonumber(item_id)
                        if not item_id or item_id <= 0 then
                            return oldSend(item_id)
                        end
                        if not isRealAvatarFrame(item_id) then
                            print("[AVFRAME] Blocked bad ID from handler:", item_id)
                            return
                        end
                        pcall(function()
                            local RAF = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
                            if RAF and RAF._RoxzFinalChange then
                                RAF._RoxzFinalChange(0, item_id)
                            elseif RAF and RAF.change_avatar_box_rsp then
                                RAF.change_avatar_box_rsp(0, item_id)
                            end
                        end)
                        pcall(function()
                            if _G.DataMgr and _G.DataMgr.UpdateAvatarBoxId then
                                _G.DataMgr.UpdateAvatarBoxId(item_id)
                            end
                            if _G.DataMgr and _G.DataMgr.roleData then
                                _G.DataMgr.roleData.cur_avatar_box_id = item_id
                            end
                        end)
                        pcall(function()
                            if _G.EventSystem and EVENTTYPE_ROLEINFO then
                                if EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO then
                                    _G.EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
                                end
                                if EVENTID_ROLEINFO_UPDATE_ROLEINFO then
                                    _G.EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_ROLEINFO)
                                end
                            end
                        end)
                    end
                end
            end
        end)

        print("[AVFRAME] Final hook installed")
        return true
    end

    if not install() then
        pcall(function()
            local t = require("common.time_ticker")
            if t and t.AddTimerOnce then
                for _, d in ipairs({1, 3, 8, 15, 30, 60}) do
                    t.AddTimerOnce(d, install)
                end
            end
        end)
    end

    pcall(function()
        if _G.NTHUY2004_ProfileCustomEquip then
            _G.NTHUY2004_ProfileCustomEquip.avatarBox = nil
        end
    end)
end)


