_G.PetUnlock.ApplyDress = function(dressID) _G.PetDressApply(getEquippedPet(), dressID) end
_G.PetUnlock.Refresh = function() applyAutoEquip(); reemit() end

print("[pet_v14_skinfix] loaded")
return _G.PetUnlock
end)()


